import React, { useState } from "react";
import { FiMenu, FiX } from "react-icons/fi";
import { useTranslation } from "gatsby-plugin-react-i18next";
import menuData from "../data/data.json";
import Icon from "../components/icon";

interface NavigationProps {
  iconFill?: string;
}

export default function Navigation({ iconFill }: NavigationProps) {
  const { t } = useTranslation();
  const [isOpen, setIsOpen] = useState(false);
  const menuItems = menuData.menu;

  // Divide los ítems en dos mitades
  const half = Math.ceil(menuItems.length / 2);
  const leftItems = menuItems.slice(0, half);
  const rightItems = menuItems.slice(half);

  return (
    <nav className="fixed h-[3.75rem] w-full px-4 sm:px-[3.75rem] text-Tofu bg-black/10 backdrop-blur-md z-50">
      <div className="flex justify-between items-center w-full h-full">
        {/* Desktop Menu */}
        <div className="hidden md:flex justify-end">
          <ul className="flex space-x-6  min-w-full">
            {leftItems.map((item, index) => (
              <li key={index}>
                <a
                  href={item === "home" ? `/` : `/${item}`}
                  className="text-primary hover:text-secondary"
                >
                  {t(`menu.${item}`)}
                </a>
              </li>
            ))}
          </ul>
        </div>

        {/* Icono centrado */}
        {/* <div className="mx-6"> */}
          <Icon className={`${iconFill} w-8 h-8`} />
        {/* </div> */}

        <div className="hidden md:flex justify-start">
          <ul className="flex space-x-6">
            {rightItems.map((item, index) => (
              <li key={index}>
                <a
                  href={item === "home" ? `/` : `/${item}`}
                  className="text-primary hover:text-secondary"
                >
                  {t(`menu.${item}`)}
                </a>
              </li>
            ))}
          </ul>
        </div>

        {/* Botón móvil */}
        <button onClick={() => setIsOpen(!isOpen)} className="md:hidden">
          {/* {isOpen ? <FiX size={24} /> : <FiMenu size={24} />} */}
          {isOpen ? <img src="./close.svg" /> : <img src="./menu.svg" />}
        </button>
      </div>

      {/* Menú móvil */}
      {isOpen && (
        <ul className="bg-neutral md:hidden shadow-md p-4 space-y-2">
          {menuItems.map((item, index) => (
            <li key={index}>
              <a
                href={item === "home" ? `/` : `/${item}`}
                className="text-accent hover:text-secondary block"
              >
                {t(`menu.${item}`)}
              </a>
            </li>
          ))}
        </ul>
      )}
    </nav>
  );
}
